    {
      "hunk_id": "H007",
      "decision": "SOL",
      "reason": "SOL preserves both research actions and their meaning; the punctuation change does not alter the sense."
    },
    {
      "hunk_id": "H008",
      "decision": "SOL",
      "reason": "SOL preserves the stealth and difficulty of detection expressed in the Korean."
    },
    {
